if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }

var stars = [];
var numStars = 28 * 4;

function setup() {
    createCanvas(windowWidth, windowHeight, WEBGL);
    for (var i = 0; i < numStars; i++) {
        var theta = random(TWO_PI);
        var phi = random(-HALF_PI, HALF_PI);
        var r = 400;
        var x = r * cos(phi) * cos(theta);
        var y = r * cos(phi) * sin(theta);
        var z = r * sin(phi);
        stars.push(createVector(x, y, z));
    }
}

function draw() {
    background(5, 6, 12);

    var beat = (window.beatEnergy || 0.0);
    var low = (window.audioLow || 0.5);
    var t = frameCount * 0.008;

    rotateX(t * 0.5);
    rotateY(t * 0.7);

    stroke('#d4af37');
    strokeWeight(3 + low * 3);
    noFill();

    push();
    rotateX(HALF_PI);
    torus(220, 2);
    pop();

    push();
    rotateX(0.41);
    stroke('#ffb703');
    torus(240, 2);
    pop();

    push();
    rotateY(HALF_PI);
    stroke('#2a9d8f');
    torus(260, 2);
    pop();

    push();
    stroke(255, 255, 255);
    strokeWeight(1);
    for (var i = 0; i < stars.length; i++) {
        var s = stars[i];
        point(s.x, s.y, s.z);
        if (i % 4 !== 0) {
            var prev = stars[i - 1];
            line(s.x, s.y, s.z, prev.x, prev.y, prev.z);
        }
    }
    pop();
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
